def table(frame):
    cols=list(frame.columns);rows=['| '+' | '.join(map(str,cols))+' |','| '+' | '.join(['---']*len(cols))+' |']
    for vals in frame.itertuples(index=False,name=None):rows.append('| '+' | '.join(str(v).replace('|','/') for v in vals)+' |')
    return '\n'.join(rows)

def digest(path):
    h=hashlib.sha256()
    with open(path,'rb') as f:
        for chunk in iter(lambda:f.read(1048576),b''):h.update(chunk)
    return h.hexdigest()

def main():
    defs=pd.read_csv(T/'selected_cluster_definitions.csv');local=pd.read_csv(T/'local_exact_results_complete.csv.gz');glob=pd.read_csv(T/'global_exact_results.csv');sens=pd.read_csv(T/'global_sensitivity_results.csv');funnel=pd.read_csv(T/'selection_funnel.csv');coords=pd.read_csv(T/'kernel_principal_coordinates.csv');null=pd.read_csv(T/'global_exact_null_distributions.csv.gz');animal=pd.read_csv(T/'analysis_animals.csv');composition=pd.read_csv(T/'animal_alternative_compositions.csv.gz').merge(animal[['sample','group']],on='sample',validate='many_to_one');coverage=pd.read_csv(T/'animal_cluster_coverage.csv.gz').merge(animal[['sample','group']],on='sample',validate='many_to_one')
    selection=json.loads((T/'selection_summary.json').read_text());inf=json.loads((T/'inference_summary.json').read_text());verify=json.loads((T/'independent_verification.json').read_text())
    summaries=composition.groupby(['cluster_id','alternative_index','junction_id','group']).agg(n_animals=('proportion','size'),mean_proportion=('proportion','mean'),sd_proportion=('proportion','std'),min_proportion=('proportion','min'),max_proportion=('proportion','max'),mean_count=('count','mean')).reset_index()
